        for name in (
            "temperature",
            "top_p",
            "top_k",
            "min_p",
            "repeat_penalty",
            "presence_penalty",
        )
    }

functions._restore_sampling_state:
def _restore_sampling_state(
    config: Any,
    state: dict[str, tuple[bool, Any]],
) -> None:
    for name, (existed, value) in state.items():
        if existed:
            setattr(config, name, value)
        else:
            with suppress(AttributeError):
                delattr(config, name)

