        def _compact_prompt_composer(self) -> None:
            prompt = self.prompt_box
            controls = self.send_button.master
            composer = prompt.master
            if hasattr(self, "_prompt_actions_frame"):
                return
            widgets = list(controls.pack_slaves())
            prompt.pack_forget()
            controls.pack_forget()
            for widget in widgets:
                widget.pack_forget()

            def grouped(items: list[Any]) -> list[list[Any]]:
                groups = []
                for widget in items:
                    if (groups and groups[-1][-1].winfo_class() in {"Label", "TLabel"}
                            and widget.winfo_class() in {"Entry", "TEntry", "TCombobox"}):
                        groups[-1].append(widget)
                    else:
                        groups.append([widget])
                return groups

            settings_groups = []
            reasoning_controls = []
            actions = []
            for group in grouped(widgets):
                first = group[0]
                setting = (
                    first.winfo_class() in {"Label", "TLabel"}
                    and first.cget("text") == "Effort"
                )
                reasoning = (
                    first.winfo_class() in {"Checkbutton", "TCheckbutton"}
                    and first.cget("text") == "Show Reasoning"
                )
                if setting:
                    settings_groups.append(group)
                elif reasoning:
                    reasoning_controls.extend(group)
                else:
                    actions.extend(group)

            if reasoning_controls:
                # Keep Effort and reasoning visibility together when the settings wrap.
                if settings_groups:
                    settings_groups[-1].extend(reasoning_controls)
                else:
                    settings_groups.append(reasoning_controls)

            access_bar = getattr(getattr(self, "access_mode_entry", None), "master", None)
            if access_bar is None:
                access_bar = getattr(self, "access_bar", None)
            access_groups = []
            if access_bar is not None:
                access_widgets = list(access_bar.pack_slaves())
                access_groups = grouped(access_widgets)
                access_bar.pack_forget()
                for widget in access_widgets:
                    widget.pack_forget()
                settings_groups.insert(0, [access_bar])

            composer.columnconfigure(0, weight=1)
            controls.grid(row=0, column=0, sticky="ew")
            controls.columnconfigure(0, weight=1)
            input_host = self.ttk.Frame(controls)
            input_host.grid(row=0, column=0, sticky="nsew")
            input_host.columnconfigure(0, weight=1)
            input_host.rowconfigure(0, weight=1)
            actions_host = self._prompt_actions_frame = self.ttk.Frame(controls)
            actions_host.grid(row=0, column=1, sticky="ne", padx=(10, 0))
            settings_host = self._prompt_settings_frame = self.ttk.Frame(controls)
            settings_host.grid(row=1, column=0, columnspan=2, sticky="ew", pady=(6, 0))
            if not settings_groups:
                settings_host.grid_remove()
            prompt.configure(height=4)
            prompt.grid(in_=input_host, row=0, column=0, sticky="nsew")
            prompt.lift()
            scrollbar = self.ttk.Scrollbar(input_host, orient="vertical", command=prompt.yview)
            scrollbar.grid(row=0, column=1, sticky="ns")
            prompt.configure(yscrollcommand=scrollbar.set)
            for index, widget in enumerate(actions):
                widget.grid(in_=actions_host, row=index // 2, column=index % 2,
                            sticky="ew", padx=(0, 4), pady=2)
                widget.lift()

            def flow(host: Any, groups: list[list[Any]], available: int,
                     sizes: dict[Any, tuple[int, int]] | None = None) -> int:
                sizes = sizes or {}
                used = top = row_height = 0
                for group in groups:
                    required = sum(sizes.get(widget, (widget.winfo_reqwidth(), 0))[0] + 8
                                   for widget in group)
                    if used and used + required > available:
                        top += row_height + 4
                        used = row_height = 0
                    for widget in group:
                        width, height = sizes.get(widget, (widget.winfo_reqwidth(), widget.winfo_reqheight()))
                        widget.place(in_=host, x=used, y=top + 2, width=width, height=height)
                        widget.lift()
                        used += width + 8
                        row_height = max(row_height, height)
                height = top + row_height + 4
                host.configure(height=height)
                return height
            state = {"pending": None, "closed": False}
            widths = {}

            def resize() -> None:
                state["pending"] = None
                if state["closed"]:
                    return
                available = max(1, settings_host.winfo_width())
                sizes = {}
                if access_bar is not None:
                    natural_width = sum(widget.winfo_reqwidth() + 8
                                        for group in access_groups for widget in group)
                    width = max(1, min(natural_width, available - 8))
                    access_bar.configure(width=width)
                    height = flow(access_bar, access_groups, width)
                    sizes[access_bar] = (width, height)
                flow(settings_host, settings_groups, available, sizes)

            def schedule() -> None:
                if state["closed"]:
                    return
                if state["pending"] is None:
                    state["pending"] = prompt.after_idle(resize)

            def configured(event: Any) -> None:
                if widths.get(event.widget) != event.width:
                    widths[event.widget] = event.width
                    schedule()

            def destroyed(event: Any) -> None:
                if event.widget is not prompt:
                    return
                state["closed"] = True
                if state["pending"] is not None:
                    try:
                        prompt.after_cancel(state["pending"])
                    except self.tk.TclError:
                        pass
                    state["pending"] = None

            settings_host.bind("<Configure>", configured, add="+")
            prompt.bind("<Destroy>", destroyed, add="+")
            schedule()

        def _prioritize_composer_layout(self) -> None:
            # Outer GUI layers still pack controls relative to Send during construction.
            self.root.after_idle(self._compact_prompt_composer)
            panel = self.send_button.master.master.master
            transcript_frame = self.transcript.frame
            siblings = panel.pack_slaves()
            index = siblings.index(transcript_frame)
            # Fixed controls get space first; only the scrollable chat should shrink.
            for sibling in reversed(siblings[index + 1:]):
                options = sibling.pack_info()
                options.pop("in", None)
                sibling.pack_forget()
                sibling.pack(**{**options, "side": "bottom"})
            options = transcript_frame.pack_info()
            options.pop("in", None)
            self.transcript.pack_forget()
            self.transcript.pack(**options)

        def _toggle_reasoning_display(self) -> None:
            self.config.show_reasoning = bool(self.reasoning_visible_var.get())
            if not self.config.show_reasoning:
                self._close_reasoning_block()
                self._cancel_reading_hold()
                self._restore_transcript_read_view()

        def _reasoning_hold_ms(self, text: str) -> int:
            try:
                rate = int(self._REASONING_READING_WPM)
            except (TypeError, ValueError):
                rate = 300
            rate = min(600, max(60, rate))
            return round(min(20.0, max(2.0, len(text.split()) * 60.0 / rate)) * 1000)

        def _cancel_reading_hold(self) -> None:
            self._reading_hold_epoch = getattr(self, "_reading_hold_epoch", 0) + 1
            token = getattr(self, "_reading_hold_after_id", None)
            self._reading_hold_after_id = None
            self._reasoning_collapse_pending = False
            if token is not None:
                self.root.after_cancel(token)

        def _capture_transcript_read_view(self) -> None:
            if not getattr(self, "_reading_follow_tail", True):
                self.transcript.mark_set("qubitz_read_view", self.transcript.index("@0,0"))
                self.transcript.mark_gravity("qubitz_read_view", "left")

        def _restore_transcript_read_view(self) -> None:
            if not getattr(self, "_reading_follow_tail", True):
                self.transcript.yview("qubitz_read_view")
            else:
                self.transcript.see("end")

        def _start_reading_hold(self, text: str) -> None:
            if (not self.config.show_reasoning or not text
                    or not getattr(self, "_reading_follow_tail", True)
                    or getattr(self, "_reading_hold_after_id", None) is not None):
                return
            epoch = getattr(self, "_reading_hold_epoch", 0)

            def finish_hold() -> None:
                if epoch != getattr(self, "_reading_hold_epoch", 0):
                    return
                self._reading_hold_after_id = None
                if getattr(self, "_reasoning_collapse_pending", False):
                    self._collapse_reasoning_turn()
                if getattr(self, "_reading_follow_tail", True):
                    self.transcript.see("end")

            # Delay completed reasoning collapse while live output keeps following.
            self._reading_hold_after_id = self.root.after(self._reasoning_hold_ms(text), finish_hold)

        def _jump_to_latest(self) -> None:
            self._cancel_reading_callbacks()
            self._reading_follow_tail = True
            self.transcript.see("end")

        def _record_transcript_scroll(self) -> None:
            token = getattr(self, "_reading_scroll_after_id", None)
            self._reading_scroll_after_id = None
            if token is not None:
                self.root.after_cancel(token)
            if not self.transcript.winfo_ismapped():
                return
            self._cancel_reading_hold()
            self._reading_follow_tail = self.transcript.yview()[1] >= 1.0 - 1e-9
            self._capture_transcript_read_view()

        def _queue_transcript_scroll_check(self, _event: Any = None) -> None:
            if self.transcript.winfo_ismapped():
                # Native scrolling runs after this binding, before the idle check.
                self._cancel_reading_hold()
                self._reading_follow_tail = False
                self._capture_transcript_read_view()
            if getattr(self, "_reading_scroll_after_id", None) is None:
                self._reading_scroll_after_id = self.root.after_idle(self._record_transcript_scroll)

        def _scroll_transcript(self, *args: Any) -> None:
            self.transcript.yview(*args)
            self._record_transcript_scroll()

        def _cancel_reading_callbacks(self) -> None:
            self._cancel_reading_hold()
            token = getattr(self, "_reading_scroll_after_id", None)
            self._reading_scroll_after_id = None
            if token is not None:
                self.root.after_cancel(token)

        def _close_reasoning_block(self) -> None:
            if not getattr(self, "_reasoning_chat_open", False):
                return
            self.transcript.configure(state="normal")
            self.transcript.insert("end", "\n\n", ("role_reasoning", "reasoning_current_marker"))
            self.transcript.configure(state="disabled")
            self._reasoning_chat_open = False
            text = getattr(self, "_reasoning_block_text", "")
            self._reasoning_block_text = ""
            self._start_reading_hold(text)

        def _toggle_reasoning_archive(self, archive_id: int) -> None:
            archives = getattr(self, "_reasoning_archives", {})
            if archive_id not in archives:
                return
            self._capture_transcript_read_view()
            self.transcript.configure(state="normal")

            def remove_bodies(number: int) -> None:
                for index in reversed(range(len(archives[number]))):
                    ranges = self.transcript.tag_ranges(f"reasoning_archive_body_{number}_{index}")
                    if ranges:
                        self.transcript.delete(ranges[0], ranges[-1])

            if getattr(self, "_reasoning_expanded_archive", None) == archive_id:
                remove_bodies(archive_id)
                self._reasoning_expanded_archive = None
            else:
                expanded = getattr(self, "_reasoning_expanded_archive", None)
                if expanded in archives:
                    remove_bodies(expanded)
                summary = self.transcript.tag_ranges(f"reasoning_archive_summary_{archive_id}")
                if summary:
                    for index, block in enumerate(archives[archive_id]):
                        position = (summary[-1] if index == 0 else
                                    f"reasoning_archive_anchor_{archive_id}_{index}")
                        self.transcript.insert(
                            position, block + "\n\n",
                            ("role_reasoning", f"reasoning_archive_body_{archive_id}_{index}"),
                        )
                    self._reasoning_expanded_archive = archive_id
            self.transcript.configure(state="disabled")
            self._restore_transcript_read_view()

        def _collapse_reasoning_turn(self, *, defer_for_reading: bool = False) -> None:
            self._close_reasoning_block()
            if defer_for_reading and not getattr(self, "_reading_follow_tail", True):
                return
            if defer_for_reading and getattr(self, "_reading_hold_after_id", None) is not None:
                self._reasoning_collapse_pending = True
                return
            self._reasoning_collapse_pending = False
            body_ranges = self.transcript.tag_ranges("reasoning_current_turn")
            bodies = list(zip(body_ranges[::2], body_ranges[1::2]))
            if not bodies:
                return
            blocks = [self.transcript.get(start, end) for start, end in bodies]
            ranges = []
            for tag in ("reasoning_current_turn", "reasoning_current_marker"):
                tagged = self.transcript.tag_ranges(tag)
                ranges.extend(zip(tagged[::2], tagged[1::2]))
            if not ranges:
                return
            by_offset = sorted(
                ranges, key=lambda pair: self.transcript.count("1.0", pair[0], "chars")[0],
            )
            self._capture_transcript_read_view()
            self.transcript.configure(state="normal")
            archive_id = getattr(self, "_reasoning_archive_serial", 0) + 1
            self._reasoning_archive_serial = archive_id
            anchor = f"reasoning_archive_anchor_{archive_id}"
            self.transcript.mark_set(anchor, bodies[0][0])
            self.transcript.mark_gravity(anchor, "left")
            for index, (start, _end) in enumerate(bodies[1:], start=1):
                block_anchor = f"reasoning_archive_anchor_{archive_id}_{index}"
                self.transcript.mark_set(block_anchor, start)
                self.transcript.mark_gravity(block_anchor, "right")
            for start, end in reversed(by_offset):
                self.transcript.delete(start, end)
            summary_tag = f"reasoning_archive_summary_{archive_id}"
            word_count = len(" ".join(blocks).split())
            summary = f"[reasoning] Provisional; {word_count} retained words. Click to show or hide.\n\n"
            self.transcript.insert(anchor, summary, ("role_reasoning", summary_tag))
            self.transcript.mark_unset(anchor)
            self.transcript.tag_configure(summary_tag, foreground="#969696", underline=True)
            self.transcript.tag_bind(
                summary_tag, "<Button-1>", lambda _event, number=archive_id: self._toggle_reasoning_archive(number),
            )
            archives = getattr(self, "_reasoning_archives", None)
            if archives is None:
                archives = self._reasoning_archives = {}
            archives[archive_id] = blocks
            while len(archives) > self._REASONING_ARCHIVE_TURNS:
                oldest = next(iter(archives))
                if getattr(self, "_reasoning_expanded_archive", None) == oldest:
                    self._toggle_reasoning_archive(oldest)
                    self.transcript.configure(state="normal")
                old_blocks = archives.pop(oldest)
                for index in range(1, len(old_blocks)):
                    self.transcript.mark_unset(f"reasoning_archive_anchor_{oldest}_{index}")
                old_summary_tag = f"reasoning_archive_summary_{oldest}"
                old_summary = self.transcript.tag_ranges(old_summary_tag)
                if old_summary:
                    old_anchor = f"reasoning_archive_anchor_{oldest}"
                    self.transcript.mark_set(old_anchor, old_summary[0])
                    self.transcript.mark_gravity(old_anchor, "left")
                    self.transcript.delete(old_summary[0], old_summary[-1])
                    self.transcript.insert(old_anchor, "[reasoning] Earlier text cleared.\n\n", ("role_reasoning",))
                    self.transcript.mark_unset(old_anchor)
                self.transcript.tag_delete(old_summary_tag)
                for index in range(len(old_blocks)):
                    self.transcript.tag_delete(f"reasoning_archive_body_{oldest}_{index}")
            self.transcript.configure(state="disabled")
            self.transcript.tag_remove("reasoning_current_turn", "1.0", "end")
            self.transcript.tag_remove("reasoning_current_marker", "1.0", "end")
            self._reasoning_display_chars = 0
            self._restore_transcript_read_view()

        def _append_stream_delta(self, message: str) -> None:
            if message:
                self._close_reasoning_block()
            self._capture_transcript_read_view()
            super()._append_stream_delta(message)
            self._restore_transcript_read_view()

        def _clear_reasoning_display(self) -> None:
            self._collapse_reasoning_turn()
            self._cancel_reading_callbacks()
            self._reasoning_block_text = ""
            self.transcript.tag_remove("reasoning_current_turn", "1.0", "end")
            self.transcript.tag_remove("reasoning_current_marker", "1.0", "end")
            self._reasoning_display_chars = 0
            self._reasoning_total_displayed = 0
            self._reasoning_channel_status = {}
            self._reasoning_status_message = "Waiting for runtime reasoning-channel diagnostics."

        def _update_reasoning_status(self, message: str) -> None:
            import json

            try:
                status = json.loads(message)
            except (TypeError, ValueError):
                return
            if not isinstance(status, dict):
                return
            self._reasoning_channel_status = status
            received = status.get("received", 0)
            forwarded = status.get("forwarded", 0)
            displayed = getattr(self, "_reasoning_total_displayed", 0)
            detail = f"Received {received}; forwarded {forwarded}; displayed {displayed} characters."
            if received:
                note = "Provisional runtime text, not verified evidence."
            elif status.get("reasoning_format") == "none":
                note = "Selected runtime reports no separate reasoning parser; this does not prove reasoning is disabled."
            else:
                note = "No separate reasoning emitted in this task yet; runtime support is not established by an empty channel."
            self._reasoning_status_message = f"{detail} {note}"

        def _append_reasoning_delta(self, text: str) -> None:
            if not self.config.show_reasoning or not text:
                return
            self._capture_transcript_read_view()
            limit = self._REASONING_DISPLAY_LIMIT
            self._ensure_transcript_tags()
            # Answer previews are replaceable; reasoning must survive their cleanup.
            self._clear_stream_preview()
            self.transcript.tag_configure("role_reasoning", foreground="#969696")
            self.transcript.configure(state="normal")
            if not getattr(self, "_reasoning_chat_open", False):
                self.transcript.insert(
                    "end", f"[reasoning] (runtime-emitted; provisional; live tail capped at {limit:,} characters)\n",
                    ("role_reasoning", "reasoning_current_marker"),
                )
                self._reasoning_chat_open = True
            self.transcript.insert("end", text[-limit:], ("role_reasoning", "reasoning_current_turn"))
            self._reasoning_block_text = (getattr(self, "_reasoning_block_text", "") + text)[-limit:]
            self._reasoning_total_displayed = getattr(self, "_reasoning_total_displayed", 0) + min(len(text), limit)
            ranges = self.transcript.tag_ranges("reasoning_current_turn")
            self._reasoning_display_chars = sum(
                self.transcript.count(start, end, "chars")[0]
                for start, end in zip(ranges[::2], ranges[1::2])
            )
            excess = self._reasoning_display_chars - limit
            if excess > 0:
                # Trim only tagged reasoning, never interleaved answers or tool receipts.
                older_chars = self._reasoning_display_chars
                for start, end in reversed(list(zip(ranges[::2], ranges[1::2]))):
                    length = self.transcript.count(start, end, "chars")[0]
                    older_chars -= length
                    remove = min(length, max(0, excess - older_chars))
                    if remove:
                        self.transcript.delete(start, f"{start}+{remove}c")
                self._reasoning_display_chars = limit
            self.transcript.configure(state="disabled")
            self._reasoning_status_message = (
                f"Provisional model text, not verified evidence; display keeps only the latest {limit:,} characters per turn."
            )
            self._restore_transcript_read_view()

        def send_prompt(self) -> None:
            if getattr(self, "_qubitz_workspace_transition", None) is not None:
                self._append_transcript("status", "Workspace transition is still in progress; no prompt was dispatched.")
                return
            super().send_prompt()

        def _start_prompt(self, prompt: str, *, queued: bool = False) -> None:
            if getattr(self, "_qubitz_workspace_transition", None) is not None:
                return
            self._clear_reasoning_display()
            super()._start_prompt(prompt, queued=queued)

        def _change_workspace(self) -> None:
            if self.busy or getattr(self, "_qubitz_close_started", False):
                self.messagebox.showinfo("Busy", "Wait for the active operation to finish before changing workspace.")
                return
            self._clear_reasoning_display()
            selected = base.pick_workspace_directory(self.config.workspace, self.filedialog, parent=self.root)
            if selected is None:
                return
            selected = Path(selected).resolve()
            if not selected.is_dir():
                self.messagebox.showerror("Invalid workspace", "Select an existing directory.")
                return
            if selected == self.config.workspace.resolve():
                return
            old_agent = self.agent
            candidate_config = base.replace(
                self.config, workspace=selected, runtime_workspace=old_agent.runtime_workspace,
            )
            # Dynamic GUI preferences are not copied by dataclasses.replace.
            candidate_config.show_reasoning = bool(self.reasoning_visible_var.get())
            state: dict[str, Any] = {"finished": threading.Event(), "agent": None, "error": None, "cleanup_started": False}
            self._qubitz_workspace_transition = state
            self.pending_prompts.clear()
            self.busy = True
            self._update_send_button()
            self.status_var.set("Switching workspace...")
            self._append_transcript("status", "Switching workspace...")

            def prepare_workspace() -> None:
                try:
                    state["agent"] = base.AgentRunner(candidate_config)
                    base.configure_project_environment(state["agent"].runtime_workspace)
                    state["cleanup_started"] = True
                    old_agent.reset_runtime()
                except Exception as exc:  # noqa: BLE001 - Surface setup/owned-cleanup failure on the Tk thread.
                    state["error"] = str(exc)
                    candidate = state["agent"]
                    if candidate is not None and not state["cleanup_started"]:
                        with suppress(Exception):
                            candidate.reset_runtime()
                finally:
                    state["finished"].set()

            def publish_workspace() -> None:
                if getattr(self, "_qubitz_close_started", False):
                    return
                if not state["finished"].is_set():
                    self.root.after(50, publish_workspace)
                    return
                self.pending_prompts.clear()
                if state["error"] is not None:
                    # A failed shutdown must not permit a second backend to start.
                    self.busy = bool(state["cleanup_started"])
                    self.status_var.set("Workspace cleanup failed; close the application." if self.busy else "Ready")
                    self._update_send_button()
                    self.messagebox.showerror("Workspace switch failed", state["error"])
                    if not self.busy:
                        self._qubitz_workspace_transition = None
                    return
                self.config = candidate_config
                self.agent = state["agent"]
                self._qubitz_workspace_transition = None
                sync_settings = getattr(self, "_sync_runtime_settings", None)
                if callable(sync_settings):
                    sync_settings()
                self.cancel_requested = False
                self.busy = False
                self._update_send_button()
                self.status_var.set("Ready")
                self._append_transcript("status", f"Workspace changed to {selected}. Pending prompts were cleared.")
                for warning in self.agent.skills.warnings:
                    self._append_transcript("status", f"Skill warning: {warning}")
                self.prompt_box.focus_set()

            threading.Thread(target=prepare_workspace, name="qubitz-owned-workspace-transition", daemon=True).start()
            self.root.after(0, publish_workspace)

        def _handle_close(self) -> None:
            if getattr(self, "_qubitz_close_started", False):
                return
            self._qubitz_close_started = True
            close_delivery = getattr(self, "_qubitz_close_gui_event_delivery", None)
            if callable(close_delivery):
                close_delivery()
            self._cancel_reading_callbacks()
            self.config._qubitz_closing = True
            self.agent.config._qubitz_closing = True
            self.pending_prompts.clear()
            self.agent.request_cancel()
            self.root.withdraw()
            finished = threading.Event()
            transition = getattr(self, "_qubitz_workspace_transition", None)
            close_agent = self.agent

            def cleanup() -> None:
                try:
                    if transition is not None:
                        transition["finished"].wait()
                        replacement = transition.get("agent")
                        if replacement is not None:
                            replacement.config._qubitz_closing = True
                            replacement.request_cancel()
                            replacement.reset_runtime()
                        if transition.get("error") is not None or not transition["cleanup_started"]:
                            close_agent.reset_runtime()
                    else:
                        close_agent.reset_runtime()
                except Exception as exc:  # noqa: BLE001 - Cleanup failures must be reported before the GUI exits.
                    print(f"[warning] Qubitz close cleanup failed: {exc}", file=sys.stderr)
                finally:
                    finished.set()

            def finish_close() -> None:
                if finished.is_set():
                    self.root.destroy()
                else:
                    self.root.after(50, finish_close)

            threading.Thread(target=cleanup, name="qubitz-owned-server-close", daemon=True).start()
            self.root.after(0, finish_close)

        def _schedule_startup_visibility_recovery(self) -> None:
            for delay_ms in (0, 250, 900):
                self.root.after(delay_ms, self._raise_gui_window)
            skip_probe = os.environ.get(
                "QUBITZ_SKIP_WSLG_VISIBILITY_PROBE",
                "",
            ).strip().casefold() in {"1", "on", "true", "yes"}
            if sys.platform.startswith("linux") and base.in_wsl() and not skip_probe:
                self.root.after(350, self._start_wslg_visibility_probe)

        def _poll_events(self) -> None:
            if getattr(self, "_qubitz_close_started", False):
                return
            if getattr(self, "_qubitz_wslg_destroy_requested", False):
                self._qubitz_wslg_destroy_requested = False
                try:
                    self.root.destroy()
                except self.tk.TclError:
                    pass
                return
            super()._poll_events()

        def _raise_gui_window(self) -> None:
            if getattr(self, "_qubitz_close_started", False):
                return
            try:
                self.root.deiconify()
                self.root.update_idletasks()
                self.root.lift()
                self.root.attributes("-topmost", True)
                self.root.focus_force()
                self.root.after(220, self._release_gui_topmost)
            except self.tk.TclError:
                pass

        def _release_gui_topmost(self) -> None:
            try:
                self.root.attributes("-topmost", False)
            except self.tk.TclError:
                pass

        def _start_wslg_visibility_probe(self) -> None:
            if getattr(self, "_qubitz_wslg_probe_started", False):
                return
            self._qubitz_wslg_probe_started = True
            threading.Thread(
                target=self._probe_wslg_visibility,
                name="qubitz-wslg-visibility",
                daemon=True,
            ).start()

        def _wslg_copy_mode_active(self) -> bool:
            log_path = Path("/mnt/wslg/weston.log")
            try:
                with log_path.open("rb") as handle:
                    handle.seek(0, os.SEEK_END)
                    size = handle.tell()
                    handle.seek(max(0, size - 262144))
                    tail = handle.read().decode("utf-8", errors="ignore")
            except OSError:
                return False
            modes = re.findall(r"RDP backend:\s+use_gfxredir\s*=\s*([01])", tail)
            return bool(modes and modes[-1] == "0")

        def _probe_wslg_visibility(self) -> None:
            copy_mode_from_log = self._wslg_copy_mode_active()
            foreground_script = r"""
$ErrorActionPreference = 'SilentlyContinue'
Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public static class QubitzWindowActivation {
    [DllImport("user32.dll")]
    public static extern bool ShowWindowAsync(IntPtr hWnd, int nCmdShow);
    [DllImport("user32.dll")]
    public static extern bool IsIconic(IntPtr hWnd);
    [DllImport("user32.dll")]
    public static extern bool SetForegroundWindow(IntPtr hWnd);
    [DllImport("user32.dll")]
    public static extern bool BringWindowToTop(IntPtr hWnd);
}
"@
$deadline = (Get-Date).AddSeconds(4)
do {
    $target = Get-Process -Name msrdc -ErrorAction SilentlyContinue |
        Where-Object { $_.MainWindowTitle -like '*AI Agent Qubitz*' } |
        Sort-Object StartTime -Descending |
        Select-Object -First 1
    if ($null -ne $target) {
        $copyMode = $target.MainWindowTitle.StartsWith('[WARN:COPY MODE]')
        # Restore only minimized windows; SW_SHOW preserves maximized/current placement.
        $showCommand = if ([QubitzWindowActivation]::IsIconic($target.MainWindowHandle)) { 9 } else { 5 }
        [void][QubitzWindowActivation]::ShowWindowAsync($target.MainWindowHandle, $showCommand)
        [void][QubitzWindowActivation]::BringWindowToTop($target.MainWindowHandle)
        [void][QubitzWindowActivation]::SetForegroundWindow($target.MainWindowHandle)
        if ($copyMode) {
            Write-Output 'copy_mode_foreground_requested'
            exit 42
        }
        Write-Output 'foreground_requested'
        exit 0
    }
    Start-Sleep -Milliseconds 200
} while ((Get-Date) -lt $deadline)
Write-Output 'window_not_found'
exit 3
"""
            result = run_windows_powershell(foreground_script, timeout_seconds=7.0)
            copy_mode_from_window = result is not None and (
                result.returncode == 42 or "copy_mode" in result.stdout.lower()
            )
            if copy_mode_from_log or copy_mode_from_window:
                self._handle_wslg_copy_mode()

        def _append_status_from_thread(self, message: str) -> None:
            self.event_queue.put(("status", message))

        def _wslg_auto_recovery_enabled(self) -> bool:
            enabled_values = {"1", "enabled", "on", "true", "yes"}
            environment_value = os.environ.get(
                "QUBITZ_AUTO_RECOVER_WSLG",
                "",
            ).strip().casefold()
            if environment_value:
                return environment_value in enabled_values
            marker_path = Path.home() / ".qubitz" / "auto_recover_wslg"
            try:
                marker_value = marker_path.read_text(
                    encoding="utf-8",
                    errors="strict",
                ).strip().casefold()
            except (OSError, UnicodeError):
                return False
            return marker_value in enabled_values

        def _handle_wslg_copy_mode(self) -> None:
            if getattr(self, "_qubitz_copy_mode_handled", False):
                return
            self._qubitz_copy_mode_handled = True
            automatic_recovery = self._wslg_auto_recovery_enabled()
            already_retried = os.environ.get("QUBITZ_WSLG_RECOVERY_ATTEMPT", "") == "1"
            if already_retried:
                message = (
                    "WSLg is still in degraded COPY MODE after one automatic recovery "
                    "attempt. Qubitz will not restart WSL again automatically."
                )
                self._append_status_from_thread(message)
                if automatic_recovery:
                    return
                run_windows_powershell(
                    """
Add-Type -AssemblyName System.Windows.Forms
[void][System.Windows.Forms.MessageBox]::Show(
    'WSLg is still in degraded COPY MODE after one recovery attempt. Qubitz will not restart WSL again automatically. Close or save other WSL work, then run wsl --shutdown manually or restart Windows.',
    'AI Agent Qubitz - WSLg recovery',
    [System.Windows.Forms.MessageBoxButtons]::OK,
    [System.Windows.Forms.MessageBoxIcon]::Error
)
""",
                    timeout_seconds=120.0,
                )
                return

            if automatic_recovery:
                if not self._launch_wslg_recovery(automatic=True):
                    self._append_status_from_thread(
                        "Automatic WSLg recovery could not start; close or save WSL "
                        "work, then run wsl --shutdown manually."
                    )
                return

            prompt_result = run_windows_powershell(
                """
Add-Type -AssemblyName System.Windows.Forms
$choice = [System.Windows.Forms.MessageBox]::Show(
    'WSLg started in degraded COPY MODE. Qubitz attempted normal foreground recovery first. If the Qubitz window is now visible and usable, choose No. If it remains invisible or unusable, choosing Yes will restart WSL, which closes every running WSL distribution and process, wait eight seconds, and relaunch this exact Qubitz variant once.',
    'AI Agent Qubitz - WSLg recovery',
    [System.Windows.Forms.MessageBoxButtons]::YesNo,
    [System.Windows.Forms.MessageBoxIcon]::Warning,
    [System.Windows.Forms.MessageBoxDefaultButton]::Button2
)
if ($choice -eq [System.Windows.Forms.DialogResult]::Yes) {
    Write-Output 'yes'
} else {
    Write-Output 'no'
}
""",
                timeout_seconds=600.0,
            )
            if prompt_result is None or "yes" not in prompt_result.stdout.lower().split():
                self._append_status_from_thread(
                    "WSLg COPY MODE detected; WSL restart and relaunch were not approved."
                )
                return
            if not self._launch_wslg_recovery(automatic=False):
                self._append_status_from_thread(
                    "WSLg recovery could not start; close or save WSL work, then run "
                    "wsl --shutdown manually."
                )

        def _launch_wslg_recovery(self, *, automatic: bool) -> bool:
            distro = os.environ.get("WSL_DISTRO_NAME", "").strip()
            script_path = str(Path(sys.argv[0]).resolve())
            working_directory = str(Path.cwd())
            launch_arguments = []
            if distro:
                launch_arguments.extend(["-d", distro])
            launch_arguments.extend(
                [
                    "--cd",
                    working_directory,
                    "--",
                    "env",
                    "QUBITZ_WSLG_RECOVERY_ATTEMPT=1",
                    sys.executable,
                    script_path,
                    *sys.argv[1:],
                ]
            )
            argument_line = subprocess.list2cmdline(launch_arguments).replace("'", "''")
            recovery_script = f"""
Start-Sleep -Milliseconds 750
& "$env:WINDIR\\System32\\wsl.exe" --shutdown | Out-Null
Start-Sleep -Seconds 8
$startInfo = New-Object System.Diagnostics.ProcessStartInfo
$startInfo.FileName = "$env:WINDIR\\System32\\wsl.exe"
$startInfo.Arguments = '{argument_line}'
$startInfo.UseShellExecute = $false
$startInfo.CreateNoWindow = $true
$startInfo.WindowStyle = [System.Diagnostics.ProcessWindowStyle]::Hidden
[void][System.Diagnostics.Process]::Start($startInfo)
"""
            recovery_encoded = encoded_powershell(recovery_script)
            launcher_script = f"""
$process = Start-Process -FilePath 'powershell.exe' -ArgumentList @(
    '-NoProfile',
    '-NonInteractive',
    '-WindowStyle',
    'Hidden',
    '-EncodedCommand',
    '{recovery_encoded}'
) -WindowStyle Hidden -PassThru
if ($null -ne $process) {{
    Write-Output 'started'
}}
"""
            result = run_windows_powershell(launcher_script, timeout_seconds=15.0)
            if result is None or "started" not in result.stdout.lower().split():
                return False
            recovery_mode = "Automatic" if automatic else "Approved"
            self._append_status_from_thread(
                f"{recovery_mode} WSLg recovery started; WSL will restart and this "
                "variant will relaunch once."
            )
            self._qubitz_wslg_destroy_requested = True
            return True

        def _update_run_control_buttons(self) -> None:
            if not hasattr(self, "steer_button") or not hasattr(self, "cancel_button"):
                return
            active = bool(getattr(self, "busy", False))
            cancelling = bool(getattr(self, "cancel_requested", False))
            state = "normal" if active and not cancelling else "disabled"
            self.steer_button.configure(state=state)
            self.cancel_button.configure(state=state)

        def _update_send_button(self) -> None:
            super()._update_send_button()
            self._update_run_control_buttons()

        def _request_cancel(self) -> None:
            requesting = self.busy and not self.cancel_requested
            super()._request_cancel()
            if requesting and self.cancel_requested:
                self._append_transcript(
                    "status",
                    "Cancellation requested for the active task; a blocking step may need "
                    "to reach its cancellation boundary first.",
                )
            self._update_run_control_buttons()

        def _append_transcript(self, role: str, message: str) -> None:
            self._close_reasoning_block()
            self._capture_transcript_read_view()
            if role == "status" and message.strip() == steering_status:
                message = (
                    "Steering update accepted; it will apply after the current step "
                    "reaches a safe boundary."
                )
            super()._append_transcript(role, message)
            self._restore_transcript_read_view()

        def _steer_active_prompt(self) -> None:
            if not self.busy or self.cancel_requested:
                return
            raw_prompt = self.prompt_box.get("1.0", "end").strip()
            if not raw_prompt:
                return
            prompt = re.sub(
                r"^/(?:btw|steer)(?:\s+|$)",
                "",
                raw_prompt,
                count=1,
                flags=re.IGNORECASE,
            ).strip()
            if not prompt:
                return
            if not self.agent.submit_side_note(prompt):
                self._append_transcript(
                    "status",
                    "Unable to steer because the active task is no longer accepting updates.",
                )
                return
            self.prompt_box.delete("1.0", "end")
            self._last_user_prompt = prompt
            self._append_transcript("steer", prompt)

        def _cancel_active_prompt(self) -> None:
            if not self.busy or self.cancel_requested:
                return
            self._request_cancel()

    base.QubitzGUI = install_gui_archive(RunControlGUI)

