def _sync_runtime_settings(self) -> None:
    super()._sync_runtime_settings()
    if hasattr(self, "_mtp_control"):
        self._mtp_control.sync()
    if hasattr(self, "temperature_var"):
        try:
            temperature = float(self.temperature_var.get().strip())
        except ValueError as exc:
            raise ValueError("Temperature must be a number.") from exc
        if temperature < 0:
            raise ValueError("Temperature must be a non-negative number.")
        is_manual_override = abs(temperature - self._temperature_profile_default) > 1e-12
        for target in (self.config, self.agent.config):
