async def list_tools(self) -> list[Any]:
    tools = await super().list_tools()
    annotated = [tool.model_copy(update={"annotations": _tool_annotations(base, tool.name)}) for tool in tools]
    annotated.append(
        base.mcp_types.Tool(
            name="execute_workflow",
            description=(
                "Execute a bounded dependency-ordered workflow using available tools. "
                "Independent read-only steps may run concurrently; mutations and all other steps remain ordered. "
                "Use ${steps.STEP_ID.structured_content.FIELD} as an exact argument value from a dependency."
            ),
            inputSchema={
                "type": "object",
                "additionalProperties": False,
                "required": ["steps"],
                "properties": {
                    "steps": {
                        "type": "array",
                        "minItems": 1,
                        "maxItems": 16,
                        "items": {
                            "type": "object",
                            "additionalProperties": False,
                            "required": ["id", "name", "arguments"],
                            "properties": {
                                "id": {
                                    "type": "string",
                                    "pattern": "^[A-Za-z][A-Za-z0-9_-]{0,47}$",
                                },
                                "name": {"type": "string", "minLength": 1},
                                "arguments": {"type": "object"},
                                "depends_on": {
                                    "type": "array",
                                    "maxItems": 15,
                                    "uniqueItems": True,
                                    "items": {"type": "string"},
                                    "default": [],
                                },
                            },
                        },
                    }
                },
            },
            annotations=base.mcp_types.ToolAnnotations(
                title="Execute Bounded Workflow",
                readOnlyHint=False,
                destructiveHint=False,
                idempotentHint=False,
                openWorldHint=False,
            ),
        )
    )
    self._qubitz_tool_contracts = {tool.name: tool for tool in annotated}
    broker = _TOOL_CALL_CONTEXT.get() or getattr(base, "_qubitz_active_permission_broker", None)
    if broker is not None:
        self._qubitz_active_broker = broker
        broker._available_tool_definitions = build_model_tools(annotated)
        owner = getattr(getattr(broker, "stop_callback", None), "__self__", None)
        if owner is not None:
            owner._unfiltered_tool_definitions = broker._available_tool_definitions
    return annotated

@staticmethod
def _tool_call_key(name: str, arguments: dict[str, Any]) -> str:
    return json.dumps(
        {"name": str(name), "arguments": arguments},
        sort_keys=True,
        ensure_ascii=True,
        default=str,
    )

async def _consume_parallel_read_only_batch(
    self,
    name: str,
    arguments: dict[str, Any],
    broker: Any,
) -> tuple[bool, Any | None]:
    key = self._tool_call_key(name, arguments)
    cached = getattr(self, "_qubitz_parallel_tool_results", {})
    queued_results = cached.get(key) or []
    if queued_results:
        result = queued_results.pop(0)
        if not queued_results:
            cached.pop(key, None)
        return True, result
    if getattr(self, "_qubitz_parallel_dispatching", False):
        return False, None
    owner = getattr(getattr(broker, "stop_callback", None), "__self__", None)
    raw_batch = list(getattr(owner, "_qubitz_pending_tool_batch", []) or [])
    if owner is not None:
        owner._qubitz_pending_tool_batch = []
    if not 2 <= len(raw_batch) <= 4:
        return False, None
    parsed: list[tuple[str, dict[str, Any]]] = []
    try:
        for item in raw_batch:
            function = item.get("function") or {}
            item_name = str(function.get("name") or "").strip()
            item_arguments = base.clean_arguments(function.get("arguments"))
            parsed.append((item_name, item_arguments))
    except Exception:
        return False, None
    if not parsed or self._tool_call_key(*parsed[0]) != key:
        return False, None
    if not all(self._parallel_read_only_tool(item_name) for item_name, _ in parsed):
        return False, None
    if broker is not None:
        broker._emit(
            f"Executing {len(parsed)} independent read-only tool calls concurrently; results remain ordered."
        )

    async def invoke(item_name: str, item_arguments: dict[str, Any]) -> Any:
        try:
            return await asyncio.wait_for(
                self.call_tool(item_name, item_arguments),
                timeout=300.0,
            )
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            return self._error_result(
                {
                    "status": "parallel_read_failed",
                    "tool": item_name,
                    "error_type": type(exc).__name__,
                    "reason": str(exc),
                }
            )

    self._qubitz_parallel_dispatching = True
    try:
        results = await asyncio.gather(
            *(invoke(item_name, item_arguments) for item_name, item_arguments in parsed)
        )
    finally:
        self._qubitz_parallel_dispatching = False
    cached = getattr(self, "_qubitz_parallel_tool_results", None)
    if cached is None:
        cached = {}
        self._qubitz_parallel_tool_results = cached
    for (item_name, item_arguments), result in zip(parsed, results, strict=True):
        item_key = self._tool_call_key(item_name, item_arguments)
        cached.setdefault(item_key, []).append(result)
    queued_results = cached.get(key) or []
    if not queued_results:
        return False, None
    result = queued_results.pop(0)
    if not queued_results:
        cached.pop(key, None)
    return True, result

@staticmethod
def _resolve_workflow_value(value: Any, completed: dict[str, dict[str, Any]]) -> Any:
    if isinstance(value, list):
        return [
            HardenedMCPHost._resolve_workflow_value(item, completed)
            for item in value
        ]
    if isinstance(value, dict):
        return {
            key: HardenedMCPHost._resolve_workflow_value(item, completed)
            for key, item in value.items()
        }
    if not isinstance(value, str):
        return value
    match = re.fullmatch(
        r"\$\{steps\.([A-Za-z][A-Za-z0-9_-]{0,47})\.([A-Za-z0-9_.-]+)\}",
        value,
    )
    if match is None:
        return value
    step_id, dotted_path = match.groups()
    if step_id not in completed:
        raise ValueError(f"Workflow reference uses unfinished step {step_id!r}.")
    resolved: Any = completed[step_id]
    for part in dotted_path.split("."):
        if isinstance(resolved, dict) and part in resolved:
            resolved = resolved[part]
        elif isinstance(resolved, list) and part.isdigit() and int(part) < len(resolved):
            resolved = resolved[int(part)]
        else:
            raise ValueError(
                f"Workflow reference path {dotted_path!r} is missing from step {step_id!r}."
            )
    return resolved

async def _execute_workflow(self, arguments: dict[str, Any], broker: Any) -> Any:
    raw_steps = list(arguments.get("steps") or [])
    steps: dict[str, dict[str, Any]] = {}
    order: list[str] = []
    available = set(getattr(self, "_qubitz_tool_contracts", {})) - {"execute_workflow"}
    for raw_step in raw_steps:
        step_id = str(raw_step.get("id") or "").strip()
        if step_id in steps:
            return self._error_result(
                {"status": "invalid_workflow", "reason": f"Duplicate step id: {step_id}"}
            )
        name = str(raw_step.get("name") or "").strip()
        if name not in available:
            return self._error_result(
                {
                    "status": "invalid_workflow",
                    "reason": f"Step {step_id!r} names unavailable tool {name!r}.",
                }
            )
        dependencies = [str(item) for item in raw_step.get("depends_on") or []]
        steps[step_id] = {
            "id": step_id,
            "name": name,
            "arguments": dict(raw_step.get("arguments") or {}),
            "depends_on": dependencies,
        }
        order.append(step_id)
    known_ids = set(steps)
    for step in steps.values():
        unknown = set(step["depends_on"]) - known_ids
        if unknown or step["id"] in step["depends_on"]:
            return self._error_result(
                {
                    "status": "invalid_workflow",
                    "reason": (
                        f"Step {step['id']!r} has invalid dependencies: "
                        f"{sorted(unknown or {step['id']})}."
                    ),
                }
            )
    completed: dict[str, dict[str, Any]] = {}
    pending = set(order)
    while pending:
        ready = [
            step_id
            for step_id in order
            if step_id in pending
            and all(dependency in completed for dependency in steps[step_id]["depends_on"])
        ]
        if not ready:
            return self._error_result(
                {"status": "invalid_workflow", "reason": "Workflow dependencies contain a cycle."}
            )
        runnable: list[str] = []
        for step_id in ready:
            dependencies = steps[step_id]["depends_on"]
            if any(not completed[dependency]["success"] for dependency in dependencies):
                completed[step_id] = {
                    "id": step_id,
                    "tool": steps[step_id]["name"],
                    "success": False,
                    "skipped": True,
                    "reason": "A dependency failed.",
                }
                pending.remove(step_id)
            else:
                runnable.append(step_id)
        if not runnable:
            continue
        parallel = [
            step_id
            for step_id in runnable
            if self._parallel_read_only_tool(steps[step_id]["name"])
        ][:4]
        selected = parallel if len(parallel) >= 2 else [runnable[0]]

        async def run_step(step_id: str) -> tuple[str, Any, dict[str, Any]]:
            step = steps[step_id]
            try:
                resolved_arguments = self._resolve_workflow_value(
                    step["arguments"], completed
                )
                operation = self.call_tool(step["name"], resolved_arguments)
                if self._parallel_read_only_tool(step["name"]):
                    result = await asyncio.wait_for(operation, timeout=300.0)
                else:
                    result = await operation
                return step_id, result, resolved_arguments
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                return (
                    step_id,
                    self._error_result(
                        {
                            "status": "workflow_step_failed",
                            "tool": step["name"],
                            "error_type": type(exc).__name__,
                            "reason": str(exc),
                        }
                    ),
                    {},
                )

        prior_dispatch = getattr(self, "_qubitz_parallel_dispatching", False)
        self._qubitz_parallel_dispatching = True
        try:
            step_results = await asyncio.gather(*(run_step(step_id) for step_id in selected))
        finally:
            self._qubitz_parallel_dispatching = prior_dispatch
        for step_id, result, resolved_arguments in step_results:
            serialized = base.serialize_mcp_result(result)
            completed[step_id] = {
                "id": step_id,
                "tool": steps[step_id]["name"],
                "arguments": resolved_arguments,
                "success": not bool(serialized.get("is_error")),
                **serialized,
            }
            pending.remove(step_id)
    ordered_results = [completed[step_id] for step_id in order]
    failed = [item["id"] for item in ordered_results if not item.get("success")]
    payload = {
        "status": "completed" if not failed else "completed_with_failures",
        "completed_steps": len(ordered_results),
        "failed_steps": failed,
        "results": ordered_results,
    }
    return self._error_result(payload) if failed else self._success_result(payload)

functions.LocalOnlyApp._build_agent_runner_class.E:
def _resolve_read_only_prompt_files(self, prompt: str) -> list[Path]:
    files: list[Path] = []
    seen: set[str] = set()
    max_files = int(getattr(base, "MAX_DIRECT_READ_FILES", 4))
    for raw_token in getattr(base, "extract_file_tokens", lambda _text: [])(prompt):
        token = _normalize_prompt_path_token(raw_token)
        if not token or token.startswith(("http://", "https://")):
            continue
        try:
            candidate = base.resolve_workspace_path(
                self.workspace,
                token,
                allow_missing=False,
                allow_external=True,
            )
        except Exception:
            continue
        if not candidate.is_file():
            continue
        resolved = candidate.resolve()
        excluded_names = {
            str(name).casefold()
            for name in getattr(base, "EXCLUDED_RETRIEVAL_FILENAMES", set())
        }
        if resolved.name.casefold() in excluded_names:
            continue
        key = str(resolved).casefold()
        if key in seen:
            continue
        if callable(getattr(base, "is_sensitive_path_name", None)) and base.is_sensitive_path_name(resolved):
            continue
        text_checker = getattr(base, "is_probably_text_file", None)
        if callable(text_checker):
            with suppress(Exception):
                if not text_checker(resolved):
                    continue
        elif resolved.suffix.lower() not in getattr(base, "TEXT_SUFFIXES", {".md", ".py", ".txt"}):
            continue
        seen.add(key)
        files.append(resolved)
        if len(files) >= max_files:
            break
    return files

def _build_read_only_workspace_context(self, prompt: str) -> str:
    self._qubitz_direct_read_receipts = {}
    files = self._resolve_read_only_prompt_files(prompt)
    if not files:
        return ""
    total_budget = max(1200, int(getattr(base, "MAX_DIRECT_READ_CHARS", 12000)))
    per_file_budget = max(800, total_budget // max(1, len(files)))
    excerpts: list[str] = []
    used_chars = 0
    for path in files:
        try:
            text = path.read_text(encoding="utf-8")
        except Exception as exc:
            rel_error = str(path)
            with suppress(Exception):
                rel_error = str(base.relative_path(path, self.workspace))
            excerpts.append(f"File read failed: {rel_error} ({type(exc).__name__}: {exc})")
            continue
        if not text.strip():
            continue
        rel = str(path)
        with suppress(Exception):
            rel = str(base.relative_path(path, self.workspace))
        remaining = max(0, total_budget - used_chars)
        if remaining <= 0:
            break
        file_budget = min(per_file_budget, remaining)
        numbered_lines: list[str] = []
        char_count = 0
        for line_number, line in enumerate(text.splitlines(), start=1):
            numbered = f"{line_number}: {line}"
            projected = char_count + len(numbered) + 1
            if projected > file_budget:
                break
            numbered_lines.append(numbered)
            char_count = projected
        if not numbered_lines:
            continue
        broker = getattr(self, "_tool_permission_broker", None)
        if broker is not None and len(numbered_lines) == len(text.splitlines()) and len(text) <= file_budget:
            self._qubitz_direct_read_receipts[str(path.resolve())] = {
                "turn_id": broker.turn_id, "workspace": str(self.workspace.resolve()), "body": text,
                "sha256": hashlib.sha256(text.encode("utf-8")).hexdigest(),
            }
        used_chars += char_count
        excerpts.append(f"File: {rel}\nExcerpt:\n" + "\n".join(numbered_lines))
    if not excerpts:
        return ""
    return "\n\n".join(
        [
            "Wrapper read-only workspace context:",
            "The wrapper read these exact text file excerpts before model or tool orchestration.",
            "The current request's explicit file targets supersede earlier unbound aliases; answer from these fresh excerpts.",
            _fence_untrusted_workspace_content("\n\n".join(excerpts)),
            "Use only this read-only context unless it is insufficient; do not edit files or run commands for this route.",
        ]
    )

def _build_metadata_or_lexical_context(self, prompt: str) -> str:
    lowered = prompt.lower()
    metadata_names: list[str] = []
    metadata_groups = (
        (r"\b(python|dependency|dependencies|package|install|pytest|ruff)\b", ("pyproject.toml", "requirements.txt", "setup.cfg", "setup.py")),
        (r"\b(node|npm|pnpm|yarn|javascript|typescript)\b", ("package.json", "pnpm-workspace.yaml", "tsconfig.json")),
        (r"\b(make|cmake|build configuration)\b", ("Makefile", "CMakeLists.txt")),
        (r"\b(docker|container|compose)\b", ("Dockerfile", "docker-compose.yml", "compose.yml")),
    )
    for pattern, names in metadata_groups:
        if re.search(pattern, lowered):
            metadata_names.extend(names)
    candidates: list[tuple[Path, int]] = []
    for name in dict.fromkeys(metadata_names):
        path = (self.workspace / name).resolve()
        if path.is_file():
            candidates.append((path, 1))

    symbols: list[str] = []
    for match in re.finditer(r"`([A-Za-z_][A-Za-z0-9_.:-]{2,80})`", prompt):
        token = match.group(1)
        if "/" not in token and "\\" not in token and not Path(token).suffix:
            symbols.append(token)
    for match in re.finditer(
        r"\b(?:class|function|method|symbol|variable|component|module)\s+([A-Za-z_][A-Za-z0-9_.:]{2,80})",
        prompt,
        re.IGNORECASE,
    ):
        symbols.append(match.group(1))
    for match in re.finditer(
        r"\b(?:fix|repair|update|change)\s+(?:the\s+)?"
        r"([A-Za-z_][A-Za-z0-9_.:]{2,80})\s+"
        r"(?:implementation|function|method)\b",
        prompt,
        re.IGNORECASE,
    ):
        symbols.append(match.group(1))
    rg = shutil.which("rg")
    if rg is not None:
        for symbol in list(dict.fromkeys(symbols))[:3]:
            completed = subprocess.run(
                [
                    rg,
                    "-n",
                    "--fixed-strings",
                    "--max-count",
                    "3",
                    "--glob",
                    "!**/.git/**",
                    "--glob",
                    "!**/.venv*/**",
                    "--glob",
                    "!**/node_modules/**",
                    symbol,
                    ".",
                ],
                cwd=self.workspace,
                capture_output=True,
                timeout=10,
                check=False,
            )
            output = base.decode_subprocess_output(completed.stdout)
            for raw_line in output.splitlines():
                path_text, separator, remainder = raw_line.partition(":")
                if not separator:
                    continue
                line_text, separator, _ = remainder.partition(":")
                if not separator or not line_text.isdigit():
                    continue
                path = (self.workspace / path_text).resolve()
                try:
                    path.relative_to(self.workspace)
                except ValueError:
                    continue
                if path.is_file():
                    candidates.append((path, int(line_text)))

    unique_candidates: list[tuple[Path, int]] = []
    seen_paths: set[str] = set()
    for path, line_number in candidates:
        key = str(path).casefold()
        if key in seen_paths:
            continue
        seen_paths.add(key)
        unique_candidates.append((path, line_number))
        if len(unique_candidates) >= 4:
            break
    if not unique_candidates:
        return ""

    excerpts: list[str] = []
    remaining_budget = max(1200, int(getattr(base, "MAX_DIRECT_READ_CHARS", 12000)))
    for path, line_number in unique_candidates:
        try:
            lines = path.read_text(encoding="utf-8", errors="ignore").splitlines()
        except OSError:
            continue
        start = max(1, line_number - 25)
        end = min(len(lines), line_number + 25)
        excerpt_lines: list[str] = []
        for current in range(start, end + 1):
            rendered = f"{current}: {lines[current - 1]}"
            if len(rendered) + 1 > remaining_budget:
                break
            excerpt_lines.append(rendered)
            remaining_budget -= len(rendered) + 1
        if excerpt_lines:
            excerpts.append(
                f"File: {base.relative_path(path, self.workspace)}\nExcerpt:\n" + "\n".join(excerpt_lines)
            )
        if remaining_budget <= 0:
            break
    if not excerpts:
        return ""
    return "\n\n".join(
        [
            "Wrapper staged metadata and lexical context:",
            "These exact local matches were resolved before semantic retrieval.",
            _fence_untrusted_workspace_content("\n\n".join(excerpts)),
            "Use these exact matches first; use tools to retrieve more context only if needed.",
        ]
    )

def _task_class_label(self, prompt: str) -> str:
    selected_route = self._selected_route_name(prompt)
    intent_provider = getattr(self, "_task_intent_for_prompt", None)
    if callable(intent_provider):
        return intent_provider(prompt, selected_route).task_kind
    return _build_task_intent(
        prompt,
        selected_route,
        coding_repair=self._is_coding_repair_task(prompt),
    ).task_kind

def _effort_step_budget_profile(self) -> tuple[int, int, int]:
    return THINKING_EFFORT_STEP_BUDGETS.get(
        self._thinking_effort(),
        THINKING_EFFORT_STEP_BUDGETS["medium"],
    )

def _effective_max_steps(self) -> int:
    configured = int(getattr(self.config, "max_steps", getattr(base, "MAX_TOOL_STEPS", 0)))
    hard_ceiling = self._effort_step_budget_profile()[2]
    if configured <= 0:
        return hard_ceiling
    return min(configured, hard_ceiling)

def _effective_prompt_max_steps(self, prompt: str) -> int:
    effective = self._effective_max_steps()
    prompt_limit: int | None = None
    retry_override = int(getattr(self, "_prompt_step_retry_override", 0) or 0)
    selected_route = self._selected_route_name(prompt)
    if retry_override < 0:
        prompt_limit = 0
    elif retry_override > 0:
        prompt_limit = retry_override
    elif selected_route == "simple_answer":
        prompt_limit = SIMPLE_DIRECT_QUESTION_STEP_CAP
    elif selected_route == "direct_existing_entrypoint":
        prompt_limit = FOREGROUND_EXISTING_SCRIPT_STEP_CAP
    if prompt_limit is None:
        return effective
    if prompt_limit <= 0:
        return 0
    if effective <= 0:
        return prompt_limit
    return min(effective, prompt_limit)

